package com.wizzadrds.theworldremembers.behavior; import com.wizzadrds.theworldremembers.relationship.Relationship; import com.wizzadrds.theworldremembers.personality.PersonalityGenerator; import com.wizzadrds.theworldremembers.stress.NpcStress; import java.util.UUID; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class NpcBehaviorEngineTest { @Test void sleepingIgnoresPlayer(){var id=UUID.randomUUID();var rel=new Relationship(id,UUID.randomUUID(),80,80,0,80,80,0,0);assertEquals(NpcDecision.IGNORE_PLAYER,new NpcBehaviorEngine().decide(NpcActivity.SLEEPING,rel,PersonalityGenerator.generate(id),new NpcStress(0)));} @Test void criticalStressLeaves(){var id=UUID.randomUUID();var rel=new Relationship(id,UUID.randomUUID(),0,0,0,0,0,0,0);assertEquals(NpcDecision.LEAVE,new NpcBehaviorEngine().decide(NpcActivity.IDLE,rel,PersonalityGenerator.generate(id),new NpcStress(100)));}}
